// A token as found by a lexical analyzer.
struct TestToken
{
	vtyTokenIdent m_tid{ 0 };
	std::string m_strText; // The characters of the token.
	std::vector< std::string > m_rgstrValues; // The strings recorded by triggers, in the order of the token's values.

	TestToken() = default;
	TestToken( vtyTokenIdent _tid, const char * _pszText )
		: m_tid( _tid ), m_strText( _pszText )
	{
	}
	TestToken( vtyTokenIdent _tid, const char * _pszText, std::initializer_list< const char * > _ilValues )
		: m_tid( _tid ), m_strText( _pszText )
	{
		for ( const char * psz : _ilValues )
			m_rgstrValues.push_back( psz );
	}
	bool operator == ( TestToken const & _r ) const
	{
		return ( m_tid == _r.m_tid ) && ( m_strText == _r.m_strText ) && ( m_rgstrValues == _r.m_rgstrValues );
	}
};
typedef std::vector< TestToken > TyRgTestTokens;

inline std::ostream & operator << ( std::ostream & _ros, TestToken const & _r )
{
	_ros << "{" << _r.m_tid << ",\"" << _r.m_strText << "\"";
	for ( std::string const & rstr : _r.m_rgstrValues )
		_ros << ",[" << rstr << "]";
	return _ros << "}";
}

// The result of tokenizing a string.
struct TokenizeResult
{
	TyRgTestTokens m_rgTokens;
	std::string m_strRemaining; // The portion of the string at which no token was found - empty when all was tokenized.

	bool operator == ( TokenizeResult const & _r ) const
	{
		return ( m_rgTokens == _r.m_rgTokens ) && ( m_strRemaining == _r.m_strRemaining );
	}
};
inline std::ostream & operator << ( std::ostream & _ros, TokenizeResult const & _r )
{
	for ( TestToken const & rtok : _r.m_rgTokens )
		_ros << rtok << " ";
	return _ros << "remaining:\"" << _r.m_strRemaining << "\"";
}

// Shorthand for declaring the expected result.
inline TokenizeResult Expect( std::initializer_list< TestToken > _ilTokens, const char * _pszRemaining = "" )
{
	TokenizeResult tr;
	tr.m_rgTokens.assign( _ilTokens );
	tr.m_strRemaining = _pszRemaining;
	return tr;
}

// Tokenize the string using the given lexical analyzer type until we reach the end or no token is found.
// _pspStart: The start state to use - required when the lexical analyzer contains more than one DFA.
template < class t_TyAnalyzer >
TokenizeResult Tokenize( const char * _psz, const typename t_TyAnalyzer::_TyStateProto * _pspStart = nullptr )
{
	typedef typename t_TyAnalyzer::_TyToken _TyToken;
	const std::string strInput( _psz );
	std::basic_string< TyTestChar > strInputChar8( strInput.begin(), strInput.end() );
	t_TyAnalyzer analyzer;
	analyzer.emplaceTransport( strInputChar8.c_str(), strInputChar8.length() );
	TokenizeResult tr;
	size_t stPosEndLast = 0;
	for ( ;; )
	{
		std::unique_ptr< _TyToken > upToken;
		if ( !analyzer.FGetToken( upToken, nullptr, nullptr, _pspStart ) )
			break;
		_l_data_range drToken;
		upToken->GetTokenDataRange( drToken );
		TestToken tt;
		tt.m_tid = upToken->GetTokenId();
		tt.m_strText = strInput.substr( drToken.begin(), drToken.end() - drToken.begin() );
		stPosEndLast = drToken.end();
		// Record any strings that triggers have stored in the token's value.
		typename _TyToken::_TyValue & rval = upToken->GetValue();
		if ( rval.FIsArray() )
		{
			for ( size_t n = 0; n < rval.GetSize(); ++n )
			{
				std::basic_string< TyTestChar > strValue;
				if ( !rval[n].FIsNull() )
					upToken->GetString( strValue, rval[n] );
				tt.m_rgstrValues.push_back( std::string( strValue.begin(), strValue.end() ) );
			}
		}
		else
		if ( !rval.FIsNull() )
		{
			// A single value is stored directly as the token's value.
			std::basic_string< TyTestChar > strValue;
			upToken->GetString( strValue, rval );
			tt.m_rgstrValues.push_back( std::string( strValue.begin(), strValue.end() ) );
		}
		tr.m_rgTokens.push_back( tt );
		if ( tr.m_rgTokens.size() > strInput.length() + 1 )
		{
			ADD_FAILURE() << "The lexical analyzer is returning empty tokens endlessly.";
			break;
		}
	}
	analyzer.ClearTokenData();
	// The remaining input starts where the lexical analyzer failed to find a token - after any skipped input.
	(void)stPosEndLast;
	tr.m_strRemaining = strInput.substr( (size_t)analyzer.GetStream().PosTokenStart() );
	return tr;
}

typedef ns_ltbasic::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerBasic;

// basic: literals, ranges, strings, or, follows, zero or more, one or more, zero or one.
// Token0: "if", Token1: identifier, Token2: number, Token3: spaces, Token4: "->", Token5: "-".
TEST( LexangBasic, SingleTokens )
{
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "abc" ), Expect( { { s_ktidToken1, "abc" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "_a1_b2" ), Expect( { { s_ktidToken1, "_a1_b2" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "42" ), Expect( { { s_ktidToken2, "42" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "3.14" ), Expect( { { s_ktidToken2, "3.14" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( " \t " ), Expect( { { s_ktidToken3, " \t " } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "->" ), Expect( { { s_ktidToken4, "->" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "-" ), Expect( { { s_ktidToken5, "-" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "" ), Expect( {} ) );
}

// When rules match the same input the earlier rule wins, when they match different lengths the longest wins.
TEST( LexangBasic, PrecedenceAndLongestMatch )
{
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "if" ), Expect( { { s_ktidToken0, "if" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "i" ), Expect( { { s_ktidToken1, "i" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "ifx" ), Expect( { { s_ktidToken1, "ifx" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "iff" ), Expect( { { s_ktidToken1, "iff" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "--" ), Expect( { { s_ktidToken5, "-" }, { s_ktidToken5, "-" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "-->" ), Expect( { { s_ktidToken5, "-" }, { s_ktidToken4, "->" } } ) );
}

TEST( LexangBasic, Sequences )
{
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "if x1 -> 42" ),
		Expect( { { s_ktidToken0, "if" }, { s_ktidToken3, " " }, { s_ktidToken1, "x1" }, { s_ktidToken3, " " }, { s_ktidToken4, "->" },
							{ s_ktidToken3, " " }, { s_ktidToken2, "42" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "a1 2b" ),
		Expect( { { s_ktidToken1, "a1" }, { s_ktidToken3, " " }, { s_ktidToken2, "2" }, { s_ktidToken1, "b" } } ) );
	// A number may have a fraction but the '.' needs digits after it: we back up to the last accepting state.
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "1.5-2" ), Expect( { { s_ktidToken2, "1.5" }, { s_ktidToken5, "-" }, { s_ktidToken2, "2" } } ) );
}

// When no token is found we stop and the rest of the input remains.
TEST( LexangBasic, NoTokenFound )
{
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "?" ), Expect( {}, "?" ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "ab ?cd" ), Expect( { { s_ktidToken1, "ab" }, { s_ktidToken3, " " } }, "?cd" ) );
	// "1." is not a number - "1" is and then '.' is not a token.
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "1." ), Expect( { { s_ktidToken2, "1" } }, "." ) );
	EXPECT_EQ( Tokenize< TyAnalyzerBasic >( "1.x" ), Expect( { { s_ktidToken2, "1" } }, ".x" ) );
}

typedef ns_lttriggers::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerTriggers;
typedef ns_lttriggerstagged::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerTriggersTagged;
typedef ns_lttriggershistory::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerTriggersHistory;
// The kind of registers for tagged DFAs that each lexical analyzer was generated with - see _l_tag.h.
static_assert( 0 == TyAnalyzerTriggers::s_knTagPolicy );
static_assert( 1 == TyAnalyzerTriggersTagged::s_knTagPolicy );
static_assert( 2 == TyAnalyzerTriggersHistory::s_knTagPolicy );

// The names of the kinds of lexical analyzer for the tests which run against more than one of them.
struct TagPolicyNames
{
	template < class t_TyAnalyzer >
	static std::string GetName( int )
	{
		return ( 0 == t_TyAnalyzer::s_knTagPolicy ) ? "Untagged" : ( 1 == t_TyAnalyzer::s_knTagPolicy ) ? "TaggedRegisters" : "TaggedHistory";
	}
};

// triggers: Token0: quoted string with the string as its value, Token1: <name> or <name=digits> with the name and digits
//	as its values, Token2: spaces, Token3: word.
// The same rules as an untagged DFA, a tagged DFA and a tagged DFA whose lexical analyzer keeps the history of the
//	triggers: all must find the same tokens with the same values.
template < class t_TyAnalyzer >
class LexangTriggers : public ::testing::Test
{
};
typedef ::testing::Types< TyAnalyzerTriggers, TyAnalyzerTriggersTagged, TyAnalyzerTriggersHistory > TyTypesAnalyzersTriggers;
TYPED_TEST_SUITE( LexangTriggers, TyTypesAnalyzersTriggers, TagPolicyNames );
TYPED_TEST( LexangTriggers, StringRecordedBetweenTriggers )
{
	EXPECT_EQ( Tokenize< TypeParam >( "\"abc\"" ), Expect( { { s_ktidToken0, "\"abc\"", { "abc" } } } ) );
	EXPECT_EQ( Tokenize< TypeParam >( "\"a b c\"" ), Expect( { { s_ktidToken0, "\"a b c\"", { "a b c" } } } ) );
	EXPECT_EQ( Tokenize< TypeParam >( "\"\"" ), Expect( { { s_ktidToken0, "\"\"", { "" } } } ) );
}

TYPED_TEST( LexangTriggers, TwoStringsOneOptional )
{
	EXPECT_EQ( Tokenize< TypeParam >( "<abc=123>" ), Expect( { { s_ktidToken1, "<abc=123>", { "abc", "123" } } } ) );
	EXPECT_EQ( Tokenize< TypeParam >( "<abc>" ), Expect( { { s_ktidToken1, "<abc>", { "abc", "" } } } ) );
	EXPECT_EQ( Tokenize< TypeParam >( "<a=1>" ), Expect( { { s_ktidToken1, "<a=1>", { "a", "1" } } } ) );
}

// The trigger data must be per token: nothing recorded for one token may leak into the next.
TYPED_TEST( LexangTriggers, TriggerDataDoesNotLeakBetweenTokens )
{
	EXPECT_EQ( Tokenize< TypeParam >( "<abc=123> <de> \"xy\" word <f=4>" ),
		Expect( { { s_ktidToken1, "<abc=123>", { "abc", "123" } }, { s_ktidToken2, " " }, { s_ktidToken1, "<de>", { "de", "" } }, { s_ktidToken2, " " },
							{ s_ktidToken0, "\"xy\"", { "xy" } }, { s_ktidToken2, " " }, { s_ktidToken3, "word" }, { s_ktidToken2, " " },
							{ s_ktidToken1, "<f=4>", { "f", "4" } } } ) );
}

// Triggers fire along the way in a token which is then not completed: no token results.
TYPED_TEST( LexangTriggers, IncompleteTokens )
{
	EXPECT_EQ( Tokenize< TypeParam >( "<abc" ), Expect( {}, "<abc" ) );
	EXPECT_EQ( Tokenize< TypeParam >( "<abc=>" ), Expect( {}, "<abc=>" ) );
	EXPECT_EQ( Tokenize< TypeParam >( "\"abc" ), Expect( {}, "\"abc" ) );
	EXPECT_EQ( Tokenize< TypeParam >( "word <abc" ), Expect( { { s_ktidToken3, "word" }, { s_ktidToken2, " " } }, "<abc" ) );
}

// With a tagged DFA the triggers fire only once a token has been found: nothing is recorded for a token which is not
//	completed - whereas with an untagged DFA the data of the triggers which fired along the way remains and must be cleared.
TYPED_TEST( LexangTriggers, IncompleteTokenLeavesNoTriggerData )
{
	if ( !TypeParam::s_kfTagged )
		return;
	std::basic_string< TyTestChar > strInput( u8"<abc=12" );
	TypeParam analyzer;
	analyzer.emplaceTransport( strInput.c_str(), strInput.length() );
	std::unique_ptr< typename TypeParam::_TyToken > upToken;
	EXPECT_FALSE( analyzer.FGetToken( upToken ) );
	EXPECT_TRUE( analyzer.FIsClearOfTokenData() );
}

typedef ns_ltexcludes::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerExcludes;

// excludes: Token0: a name which is not "xml", Token1: spaces.
TEST( LexangExcludes, ExcludedStringIsNotAToken )
{
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "abc" ), Expect( { { s_ktidToken0, "abc" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "xm" ), Expect( { { s_ktidToken0, "xm" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "xmlx" ), Expect( { { s_ktidToken0, "xmlx" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "axml" ), Expect( { { s_ktidToken0, "axml" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "xml" ), Expect( {}, "xml" ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "ab xml" ), Expect( { { s_ktidToken0, "ab" }, { s_ktidToken1, " " } }, "xml" ) );
	EXPECT_EQ( Tokenize< TyAnalyzerExcludes >( "xmla xm" ), Expect( { { s_ktidToken0, "xmla" }, { s_ktidToken1, " " }, { s_ktidToken0, "xm" } } ) );
}

typedef ns_ltcompletes::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerCompletes;

// completes: Token0: a comment "<!--" up to the first "-->", Token1: word, Token2: spaces.
TEST( LexangCompletes, StopsAtFirstEnd )
{
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!---->" ), Expect( { { s_ktidToken0, "<!---->" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!-- a comment -->" ), Expect( { { s_ktidToken0, "<!-- a comment -->" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!-- a - b -- c > d -->" ), Expect( { { s_ktidToken0, "<!-- a - b -- c > d -->" } } ) );
	// The comment ends at the first "-->" even though more of the input could be matched by the comment characters.
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!--a-->b" ), Expect( { { s_ktidToken0, "<!--a-->" }, { s_ktidToken1, "b" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!--a--> <!--b-->" ),
		Expect( { { s_ktidToken0, "<!--a-->" }, { s_ktidToken2, " " }, { s_ktidToken0, "<!--b-->" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!--a--><!--b-->" ), Expect( { { s_ktidToken0, "<!--a-->" }, { s_ktidToken0, "<!--b-->" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "word <!--a-->" ), Expect( { { s_ktidToken1, "word" }, { s_ktidToken2, " " }, { s_ktidToken0, "<!--a-->" } } ) );
}

TEST( LexangCompletes, UnterminatedIsNotAToken )
{
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!-- a comment" ), Expect( {}, "<!-- a comment" ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "<!-- a --" ), Expect( {}, "<!-- a --" ) );
	EXPECT_EQ( Tokenize< TyAnalyzerCompletes >( "ab <!--" ), Expect( { { s_ktidToken1, "ab" }, { s_ktidToken2, " " } }, "<!--" ) );
}

typedef ns_ltlookahead::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookahead;

// lookahead: Token0: a name followed by '(', Token1: a name followed by "::", Token2: any other name,
//	Token3: one of "():", Token4: spaces. The trailing context is not part of the token.
TEST( LexangLookahead, TrailingContextIsNotPartOfToken )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "abc" ), Expect( { { s_ktidToken2, "abc" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "abc(" ), Expect( { { s_ktidToken0, "abc" }, { s_ktidToken3, "(" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "abc::" ), Expect( { { s_ktidToken1, "abc" }, { s_ktidToken3, ":" }, { s_ktidToken3, ":" } } ) );
	// A single ':' is not the trailing context of the scope rule.
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "abc:" ), Expect( { { s_ktidToken2, "abc" }, { s_ktidToken3, ":" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "abc )" ), Expect( { { s_ktidToken2, "abc" }, { s_ktidToken4, " " }, { s_ktidToken3, ")" } } ) );
}

TEST( LexangLookahead, Sequences )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "ns::fn(arg)" ),
		Expect( { { s_ktidToken1, "ns" }, { s_ktidToken3, ":" }, { s_ktidToken3, ":" }, { s_ktidToken0, "fn" }, { s_ktidToken3, "(" },
							{ s_ktidToken2, "arg" }, { s_ktidToken3, ")" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookahead >( "a( b:: c" ),
		Expect( { { s_ktidToken0, "a" }, { s_ktidToken3, "(" }, { s_ktidToken4, " " }, { s_ktidToken1, "b" }, { s_ktidToken3, ":" }, { s_ktidToken3, ":" },
							{ s_ktidToken4, " " }, { s_ktidToken2, "c" } } ) );
}

typedef ns_ltlookaheadambig::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadAmbig;

// lookaheadambig: Token0: a*b when followed by 'c', Token1: "ab", Token2: "aab", Token3: "c", Token4: "a", Token7: spaces.
// The end of the lookahead rule's token coincides with the end of "ab" and of "aab": each must still be its own token.
TEST( LexangLookaheadAmbig, LookaheadEndCoincidesWithOtherRules )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "ab" ), Expect( { { s_ktidToken1, "ab" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "aab" ), Expect( { { s_ktidToken2, "aab" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "ab aab ab" ),
		Expect( { { s_ktidToken1, "ab" }, { s_ktidToken7, " " }, { s_ktidToken2, "aab" }, { s_ktidToken7, " " }, { s_ktidToken1, "ab" } } ) );
}

TEST( LexangLookaheadAmbig, LookaheadRuleMatchesLongest )
{
	// With the trailing context the lookahead rule matches more input than the other rules and so it wins.
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "abc" ), Expect( { { s_ktidToken0, "ab" }, { s_ktidToken3, "c" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "aabc" ), Expect( { { s_ktidToken0, "aab" }, { s_ktidToken3, "c" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "aaabc" ), Expect( { { s_ktidToken0, "aaab" }, { s_ktidToken3, "c" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "bc" ), Expect( { { s_ktidToken0, "b" }, { s_ktidToken3, "c" } } ) );
	// Without the trailing context "aaab" is not a token: "a" is, and then "aab".
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadAmbig >( "aaab" ), Expect( { { s_ktidToken4, "a" }, { s_ktidToken2, "aab" } } ) );
}

typedef ns_ltlookaheadtwo::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadTwo;

// lookaheadtwo: Token0: "a" when followed by "bc", Token1: "ab" when followed by "c", Token2: "b", Token3: "c", Token4: "a".
// Both lookahead rules match "abc" - the earlier rule wins. The analyzer must keep track of where the token of each ends.
TEST( LexangLookaheadTwo, TwoLookaheadRulesInProgress )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadTwo >( "abc" ), Expect( { { s_ktidToken0, "a" }, { s_ktidToken2, "b" }, { s_ktidToken3, "c" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadTwo >( "ab" ), Expect( { { s_ktidToken4, "a" }, { s_ktidToken2, "b" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadTwo >( "abb" ), Expect( { { s_ktidToken4, "a" }, { s_ktidToken2, "b" }, { s_ktidToken2, "b" } } ) );
}

typedef ns_ltlookaheadoverlap::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadOverlap;

// lookaheadoverlap: Token0: one or more 'x's when followed by "xy", Token1: "x", Token2: "y".
// The end of the token can also match the beginning of the trailing context: the last point at which the token could
//	have ended is then not where it ends - the remainder must be matched by the trailing context.
TEST( LexangLookaheadOverlap, TokenEndOverlapsTrailingContext )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "xxxy" ), Expect( { { s_ktidToken0, "xx" }, { s_ktidToken1, "x" }, { s_ktidToken2, "y" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "xxy" ), Expect( { { s_ktidToken0, "x" }, { s_ktidToken1, "x" }, { s_ktidToken2, "y" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "xx" ), Expect( { { s_ktidToken1, "x" }, { s_ktidToken1, "x" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "xxxxxxy" ), Expect( { { s_ktidToken0, "xxxxx" }, { s_ktidToken1, "x" }, { s_ktidToken2, "y" } } ) );
}

// The token of a lookahead rule is never empty: "xy" is not matched by the lookahead rule.
TEST( LexangLookaheadOverlap, TokenIsNeverEmpty )
{
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "xy" ), Expect( { { s_ktidToken1, "x" }, { s_ktidToken2, "y" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadOverlap >( "y" ), Expect( { { s_ktidToken2, "y" } } ) );
}

typedef ns_ltlookaheadsplit::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadSplit;

// lookaheadsplit: Token0: "a" or "ab" when followed by "bc" or "c", Token1: one or more 'a's when followed by any
//	number of 'a's and then a 'b', Token2: "a", Token3: "b", Token4: "c".
// When the token could end in more than one place it is the longest token for which the rest is the trailing context.
TEST( LexangLookaheadSplit, LongestTokenWithMatchingTrailingContext )
{
	// "abc" is "a" then "bc" or "ab" then "c": the token is "ab".
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "abc" ), Expect( { { s_ktidToken0, "ab" }, { s_ktidToken4, "c" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "ac" ), Expect( { { s_ktidToken0, "a" }, { s_ktidToken4, "c" } } ) );
	// All of the 'a's may be the token since the trailing context needs only the 'b'.
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "aaab" ), Expect( { { s_ktidToken1, "aaa" }, { s_ktidToken3, "b" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "ab" ), Expect( { { s_ktidToken1, "a" }, { s_ktidToken3, "b" } } ) );
	// The second rule needs at least one 'a' for its token.
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "b" ), Expect( { { s_ktidToken3, "b" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "aaa" ), Expect( { { s_ktidToken2, "a" }, { s_ktidToken2, "a" }, { s_ktidToken2, "a" } } ) );
	EXPECT_EQ( Tokenize< TyAnalyzerLookaheadSplit >( "aabc" ),
		Expect( { { s_ktidToken1, "aa" }, { s_ktidToken3, "b" }, { s_ktidToken4, "c" } } ) );
}

typedef ns_ltlookaheadvar::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadVar;
typedef ns_ltlookaheadvartagged::TGetLexicalAnalyzer< TyTestLexTraits > TyAnalyzerLookaheadVarTagged;
